1	/* ============================ Lái xe: mạng đường nhiều tầng (DrNet) ============================
2	   Mạng đường là danh sách ô mặt đường chữ nhật thẳng trục, mỗi ô có hàm cao độ riêng. Ô chồng nhau trên mặt bằng
3	   (đường ven sông dưới dốc cầu, đường trên hầm) tách tầng nhờ so cao độ với cao độ hiện tại của xe (± stepMax).
4	   Thuần toán học: chỉ import CONFIG; không dựng cảnh, không đụng DOM. Dữ liệu ô sinh ở roadData.ts. */
5	import { CONFIG } from '../../config';
6	
7	export interface DrPad { id: string; kind: 'road' | 'bridge' | 'tunnel' | 'slip' | 'junction'; x0: number; x1: number; z0: number; z1: number; y: (x: number, z: number) => number; gate?: string }
8	export interface DrSolid { kind: 'rect' | 'circle'; x0?: number; x1?: number; z0?: number; z1?: number; cx?: number; cz?: number; r?: number; y0: number; y1: number }   // y0..y1: cao độ tuyệt đối (m) mà vật cản chiếm
9	export interface DrNet { pads: DrPad[]; solids: DrSolid[]; closed: Set<string> }
10	
11	const REACH_STEP = 2;                                               // m — bước lưới mẫu của drReach: ô hẹp nhất 3,35 m nên ô nào cũng có điểm mẫu; khe hẹp hơn bước (dải giữa Thuận Phước 1,0 m) có thể bị bước qua, nên drReach chỉ để kiểm liên thông
12	
13	export function drMakeNet(pads: DrPad[], solids: DrSolid[]): DrNet {
14	  return { pads, solids: solids.slice(), closed: new Set() };
15	}
16	/* net.solids chỉ được thêm bằng push (chỉ mục lưới của collide.ts dựa vào điều đó); barie Cầu sông Hàn chặn bằng cổng của ô, không thêm / xóa vật cản */
17	export function drAddSolids(net: DrNet, more: DrSolid[]): void {
18	  for (const s of more) net.solids.push(s);
19	}
20	/* Đóng / mở cổng: ô mang cổng đang đóng coi như không có (nhịp quay Cầu sông Hàn khi cầu quay) */
21	export function drSetGate(net: DrNet, gate: string, closed: boolean): void {
22	  if (closed) net.closed.add(gate); else net.closed.delete(gate);
23	}
24	
25	/* Chỉ số ô chứa (x, z) có cao độ gần yRef nhất trong ± stepMax; −1 nếu không có. Duyệt tuyến tính, không cấp phát */
26	function drPadAt(net: DrNet, x: number, z: number, yRef: number): number {
27	  const pads = net.pads, step = CONFIG.drive.stepMax;
28	  let best = -1, bestD = Infinity;
29	  for (let i = 0; i < pads.length; i++) {
30	    const p = pads[i];
31	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1) continue;
32	    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
33	    const d = Math.abs(p.y(x, z) - yRef);
34	    if (d <= step && d < bestD) { best = i; bestD = d; }
35	  }
36	  return best;
37	}
38	/* Cao độ mặt đường tại (x, z) ở tầng gần yRef nhất; NaN nếu không có ô nào cùng tầng */
39	export function drGround(net: DrNet, x: number, z: number, yRef: number): number {
40	  const i = drPadAt(net, x, z, yRef);
41	  return i < 0 ? NaN : net.pads[i].y(x, z);
42	}
43	
44	/* Khung bao mặt bằng và cao độ của mọi ô (cao độ lấy mẫu mỗi ≤ 2 m theo hai trục) */
45	export function drBounds(net: DrNet): { x0: number; x1: number; z0: number; z1: number; yMin: number; yMax: number } {
46	  const b = { x0: Infinity, x1: -Infinity, z0: Infinity, z1: -Infinity, yMin: Infinity, yMax: -Infinity };
47	  for (const p of net.pads) {
48	    b.x0 = Math.min(b.x0, p.x0); b.x1 = Math.max(b.x1, p.x1); b.z0 = Math.min(b.z0, p.z0); b.z1 = Math.max(b.z1, p.z1);
49	    const nx = Math.ceil((p.x1 - p.x0) / 2), nz = Math.ceil((p.z1 - p.z0) / 2);
50	    for (let i = 0; i <= nx; i++) for (let j = 0; j <= nz; j++) {
51	      const y = p.y(p.x0 + (p.x1 - p.x0) * i / nx, p.z0 + (p.z1 - p.z0) * j / nz);
52	      if (y < b.yMin) b.yMin = y; if (y > b.yMax) b.yMax = y;
53	    }
54	  }
55	  return b;
56	}
57	
58	/* Id các ô tới được từ (x, z, y): loang 4 hướng trên lưới mẫu 2 m neo tại điểm xuất phát; mỗi bước tra drGround từ cao độ điểm trước,
59	   nên chỉ đổi tầng ở chỗ hai ô nối nhau cùng cao độ. Trạng thái = (điểm lưới, ô). Dùng cho test và kiểm dữ liệu, không gọi mỗi khung */
60	export function drReach(net: DrNet, x: number, z: number, y: number): Set<string> {
61	  const out = new Set<string>();
62	  const p0 = drPadAt(net, x, z, y);
63	  if (p0 < 0) return out;
64	  const NP = net.pads.length, OFF = 1 << 14, SPAN = 1 << 15;    // chỉ số lưới ±16 384 bước (±32 km)
65	  const key = (i: number, j: number, p: number) => ((i + OFF) * SPAN + (j + OFF)) * NP + p;
66	  const seen = new Set<number>(), qi: number[] = [0], qj: number[] = [0], qp: number[] = [p0];
67	  seen.add(key(0, 0, p0)); out.add(net.pads[p0].id);
68	  const DI = [1, -1, 0, 0], DJ = [0, 0, 1, -1];
69	  for (let h = 0; h < qi.length; h++) {
70	    const i = qi[h], j = qj[h], pad = net.pads[qp[h]];
71	    const cx = x + i * REACH_STEP, cz = z + j * REACH_STEP, cy = pad.y(cx, cz);
72	    for (let d = 0; d < 4; d++) {
73	      const ni = i + DI[d], nj = j + DJ[d];
74	      const np = drPadAt(net, x + ni * REACH_STEP, z + nj * REACH_STEP, cy);
75	      if (np < 0) continue;
76	      const k = key(ni, nj, np);
77	      if (seen.has(k)) continue;
78	      seen.add(k); qi.push(ni); qj.push(nj); qp.push(np); out.add(net.pads[np].id);
79	    }
80	  }
81	  return out;
82	}
