56	  const fx: number[] = [], fz: number[] = [], rx: number[] = [], rz: number[] = [];
57	  const yaw0 = s.yaw;
58	  while (s.yaw - yaw0 < 2 * Math.PI) {
59	    s.v = 2; drStep(s, g, net, [], 0, DT);
60	    const cx = Math.cos(s.yaw) * L / 2, cz = -Math.sin(s.yaw) * L / 2;
61	    fx.push(s.x + cx); fz.push(s.z + cz); rx.push(s.x - cx); rz.push(s.z - cz);
62	  }
63	  const radius = (xs: number[], zs: number[]) => {
64	    const mx = xs.reduce((a, b) => a + b) / xs.length, mz = zs.reduce((a, b) => a + b) / zs.length;
65	    return xs.reduce((a, x, i) => a + Math.hypot(x - mx, zs[i] - mz), 0) / xs.length;
66	  };
67	  const rf = radius(fx, fz), rr = radius(rx, rz);
68	  assert.ok(Math.abs(rf - P.turnRadius) <= 0.25, `trục trước r = ${rf}`);
69	  assert.ok(Math.abs(rr - Math.sqrt(P.turnRadius ** 2 - L * L)) <= 0.25, `trục sau r = ${rr}`);
70	  assert.ok(s.steer > 0, 'steer > 0 là rẽ trái, yaw tăng');
71	});
