  const dry = stopDist(15, inp(0, 1, 0, false, 1)), wet = stopDist(15, inp(0, 1, 0, false, 0));
  assert.ok(wet >= 1.2 * dry, `khô ${dry} m, ướt ${wet} m`);
});

test('đứng yên: bẻ lái không xoay, không nghiêng', () => {
  const net = square(), s = state(10, 20, 0.7);
